/// A real, checked source — never auto-generated. [note] carries an honest
/// caveat when the evidence is preliminary or weaker than the claim might
/// suggest, rather than letting the benefit text stand unqualified.
class CatalogSource {
  const CatalogSource({required this.title, required this.url, this.note});
  final String title;
  final String url;
  final String? note;
}
